#!/bin/bash
# service.sh - 첫 인자에 따라 다르게 동작한다
# 사용법: ./service.sh {start|stop|restart|status}

case "$1" in
    start)
        echo "서비스를 시작합니다"
        ;;
    stop)
        echo "서비스를 정지합니다"
        ;;
    restart|reload)
        echo "서비스를 재시작합니다"
        ;;
    status)
        echo "서비스 상태를 확인합니다"
        ;;
    *)
        echo "사용법: $0 {start|stop|restart|status}"
        exit 1
        ;;
esac
